import csv
import io


def parse_csv(raw_csv: str):
    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, row in enumerate(records) if sum(bool(cell.strip()) for cell in row) >= 2),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if any(cell.strip() for cell in row)),
            0,
        )

    columns = list(records[header_index])
    rows = records[header_index + 1:]
    width = max([len(columns)] + [len(row) for row in rows])

    used_names = set(columns)
    for index in range(len(columns), width):
        base = "extra_column_" + str(index + 1)
        name = base
        suffix = 2
        while name in used_names:
            name = base + "_" + str(suffix)
            suffix += 1
        columns.append(name)
        used_names.add(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
